// ============================================================
// ESCALATION HANDLER: Prepare Response (v3.0)
// ============================================================

const context = $json;

const responseMessage = '🤝 Это важный вопрос. Мне нужно уточнить детали у руководства.\n\nЯ передал ваш вопрос HR-специалисту. Вам ответят в ближайшее время!\n\nА пока можем продолжить знакомство — расскажите о себе! 😊';

return {
  // Context passthrough
  user_id: context.user_id,
  chat_id: context.chat_id,
  session_id: context.session_id,
  user_message: context.user_message,
  known_data: context.known_data,
  language: context.language,
  route_category: context.route_category,
  first_name: context.first_name,

  // Response
  response_message: responseMessage,
  final_message: responseMessage,
  extracted_data: context.known_data || {},
  interview_complete: false,
  show_language_buttons: false,
  needs_escalation: true,

  // HR notification data
  hr_notification: {
    type: 'escalation',
    message: `🆘 ЭСКАЛАЦИЯ\n\n👤 Кандидат: ${context.first_name || context.known_data?.first_name || 'Неизвестно'}\n💬 Вопрос: ${context.user_message}\n\n⚠️ Требуется ответ HR`,
    user_id: context.user_id,
    chat_id: context.chat_id
  }
};
